// HMAC-SHA256 서명 검증 — NestJS 와 공유 비밀키 사용
const crypto = require('crypto');
const secret = $env.ONQUEST_WEBHOOK_SECRET;
if (!secret) throw new Error('ONQUEST_WEBHOOK_SECRET is not configured');

const headers = $input.first().headers;
const signature = headers['x-onquest-signature'];
const timestamp = headers['x-onquest-timestamp'];
if (!signature || !timestamp) throw new Error('Missing signature headers');

// 재전송 방어 — 5분 윈도우
const driftMs = Math.abs(Date.now() - new Date(timestamp).getTime());
if (driftMs > 5 * 60 * 1000) throw new Error('Timestamp out of window');

const body = JSON.stringify($input.first().json);
const expected = crypto.createHmac('sha256', secret).update(body).digest('hex');
if (signature !== expected) throw new Error('Invalid signature');

return $input.all();

